import { Plus, Users, Target, X, Check, Calendar, TrendingUp, ChevronLeft, Trash2, Zap, Grid, Home, Pencil, Star, Phone } from "lucide-react";

const LOGO_B64 = "data:image/png;base64,";

const BASE_PRICE = 8;
const REFILL_PRICE = 1;
const START_BALLS = 120;
const REFILL_BALLS = 25;

const SLOTS = [
  { id: 1, label: "9:00 - 11:00", short: "9-11", base: "09:00", min: "08:30", max: "09:30" },
  { id: 2, label: "11:00 - 13:00", short: "11-1", base: "11:00", min: "10:30", max: "11:30" },
  { id: 3, label: "14:00 - 16:00", short: "2-4", base: "14:00", min: "13:30", max: "14:30" },
  { id: 4, label: "16:00 - 18:00", short: "4-6", base: "16:00", min: "15:30", max: "16:00" },
];

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(":").map(Number);
  return h * 60 + m;
}

function slotForTime(hhmm) {
  const mins = toMinutes(hhmm);
  if (mins == null) return null;
  return SLOTS.find((s) => mins >= toMinutes(s.min) && mins <= toMinutes(s.max)) || null;
}

function localDateStr(d) {
  const offset = d.getTimezoneOffset() * 60000;
  return new Date(d.getTime() - offset).toISOString().slice(0, 10);
}

function weekDates(anchor) {
  const d = new Date(anchor + "T00:00:00");
  d.setDate(d.getDate() - d.getDay());
  return Array.from({ length: 7 }, (_, i) => {
    const dd = new Date(d);
    dd.setDate(d.getDate() + i);
    return localDateStr(dd);
  });
}

const uid = () => Math.random().toString(36).slice(2, 10);
const todayStr = () => localDateStr(new Date());

function playerTotal(p) {
  return BASE_PRICE + p.refills * REFILL_PRICE;
}
function playerBalls(p) {
  return START_BALLS + p.refills * REFILL_BALLS;
}
function reservationTotal(r) {
  return r.players.reduce((s, p) => s + playerTotal(p), 0);
}
function reservationPaid(r) {
  let paid;
  if (r.paymentMode === "grupal") {
    paid = r.groupPaid ? reservationTotal(r) : 0;
  } else {
    paid = r.players.reduce((s, p) => s + (p.paid ? playerTotal(p) : 0), 0);
  }
  if (r.deposit && r.deposit.status === "aplicado" && !r.deposit.playerId) {
    paid += r.deposit.amount;
  }
  return Math.min(paid, reservationTotal(r));
}

function exampleReservations() {
  const dates = weekDates(todayStr());
  const mk = (dayIdx, time, groupName, count, paymentMode, opts = {}) => ({
    id: uid(),
    date: dates[dayIdx],
    time,
    groupName,
    paymentMode,
    expectedCount: count,
    groupPaid: !!opts.groupPaid,
    status: opts.cancelled ? "cancelada" : "activa",
    createdAt: Date.now(),
    players:
      opts.players ||
      (opts.empty
        ? []
        : Array.from({ length: count }, (_, i) => ({
            id: uid(),
            name: opts.names?.[i] || `Jugador ${i + 1}`,
            refills: opts.refills?.[i] ?? 0,
            paid: paymentMode === "individual" ? !!opts.paid?.[i] : false,
          }))),
  });

  return [
    // Sábado 9-11, ya jugado, individual, algunos pagaron
    mk(6, "09:00", "Cumpleaños Sofía", 8, "individual", {
      names: ["Sofía", "Mateo", "Valentina", "Emilio", "Camila", "Noah", "Isabella", "Liam"],
      refills: [2, 0, 1, 0, 3, 0, 1, 0],
      paid: [true, true, false, true, false, true, false, false],
    }),
    // Sábado 2-4, grupal, ya pagado
    mk(6, "14:00", "Empresa TechCorp", 12, "grupal", { groupPaid: true }),
    // Sábado 4-6, solo reservado (sin llenar aún)
    mk(6, "16:00", "Familia Pérez", 6, "individual", { empty: true }),
    // Domingo 11-1, movido 30 min antes, grupal sin pagar
    mk(0, "10:30", "Despedida de soltero", 10, "grupal", { groupPaid: false }),
    // Miércoles 4-6 adelantado (regla especial), reservado
    mk(3, "15:30", "Colegio San Francisco", 15, "individual", { empty: true }),
    // Viernes 9-11, jugado y pagado individual completo
    mk(5, "09:30", "Grupo oficina Ibarra", 7, "individual", {
      refills: [1, 1, 0, 2, 0, 1, 0],
      paid: [true, true, true, true, true, true, true],
    }),
    // Martes 2-4, no llegó el grupo, se canceló
    mk(2, "14:00", "Grupo Otavalo", 10, "individual", { empty: true, cancelled: true }),
  ];
}

async function withRetries(fn, retries = 2, delayMs = 700) {
  let lastErr;
  for (let i = 0; i <= retries; i++) {
    try {
      return await fn();
    } catch (e) {
      lastErr = e;
      if (i < retries) await new Promise((r) => setTimeout(r, delayMs));
    }
  }
  throw lastErr;
}

const SUPABASE_URL = "https://lzoolmmlottscfcsonmk.supabase.co";
const SUPABASE_KEY = "sb_publishable_cwk5ODrNHxNvZ1yoewVWfg_2-AgbWm5";

async function sb(path, options = {}) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1${path}`, {
    ...options,
    headers: {
      apikey: SUPABASE_KEY,
      "Content-Type": "application/json",
      Prefer: options.prefer || "return=representation",
      ...(options.headers || {}),
    },
  });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Supabase ${res.status}: ${text}`);
  }
  const text = await res.text();
  if (!text) return null;
  return JSON.parse(text);
}

export default function App() {
  const [reservations, setReservations] = useState(null);
  const [favorites, setFavorites] = useState([]);
  const [view, setView] = useState("inicio"); // inicio | lista | nueva | detalle | reporte | semana | favoritos
  const [activeId, setActiveId] = useState(null);
  const [saving, setSaving] = useState(false);
  const [loadError, setLoadError] = useState(null);
  const [prefill, setPrefill] = useState(null);
  const [pendingRetry, setPendingRetry] = useState(null);

  useEffect(() => {
    (async () => {
      let loaded = [];
      try {
        const rows = await withRetries(() => sb("/app_data?id=eq.reservations&select=data"));
        if (rows && rows.length > 0 && Array.isArray(rows[0].data) && rows[0].data.length > 0) {
          loaded = rows[0].data;
        } else {
          loaded = exampleReservations();
          await withRetries(() =>
            sb("/app_data", {
              method: "POST",
              prefer: "resolution=merge-duplicates,return=minimal",
              body: JSON.stringify({ id: "reservations", data: loaded }),
            })
          );
        }
      } catch (e) {
        loaded = exampleReservations();
        setLoadError(e.message || String(e));
      }
      setReservations(loaded);

      try {
        const favRows = await withRetries(() => sb("/app_data?id=eq.favorites&select=data"));
        if (favRows && favRows.length > 0 && Array.isArray(favRows[0].data)) {
          setFavorites(favRows[0].data);
        }
      } catch (e) {
        // no favorites yet, ignore
      }
    })();
  }, []);

  function persistFavorites(next) {
    setFavorites(next);
    withRetries(() =>
      sb("/app_data", {
        method: "POST",
        prefer: "resolution=merge-duplicates,return=minimal",
        body: JSON.stringify({ id: "favorites", data: next, updated_at: new Date().toISOString() }),
      })
    ).catch((e) => setLoadError(e.message || String(e)));
  }

  const saveTimerRef = useRef(null);
  const latestDataRef = useRef(null);

  async function doSave() {
    const next = latestDataRef.current;
    setSaving(true);
    try {
      await withRetries(() =>
        sb("/app_data", {
          method: "POST",
          prefer: "resolution=merge-duplicates,return=minimal",
          body: JSON.stringify({ id: "reservations", data: next, updated_at: new Date().toISOString() }),
        })
      );
      setPendingRetry(null);
    } catch (e) {
      setLoadError(e.message || String(e));
      setPendingRetry(() => next);
    } finally {
      setSaving(false);
    }
  }

  function persist(next) {
    setReservations(next);
    latestDataRef.current = next;
    setSaving(true);
    if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    saveTimerRef.current = setTimeout(doSave, 900);
  }

  function retrySave() {
    if (pendingRetry) {
      latestDataRef.current = pendingRetry;
      doSave();
    }
  }

  const active = useMemo(
    () => (reservations || []).find((r) => r.id === activeId) || null,
    [reservations, activeId]
  );

  function updateReservation(id, updater) {
    const next = reservations.map((r) => (r.id === id ? updater(r) : r));
    persist(next);
  }

  function deleteReservation(id) {
    persist(reservations.filter((r) => r.id !== id));
    setView("lista");
  }

  function createReservation(data) {
    const r = {
      id: uid(),
      date: data.date,
      time: data.time,
      groupName: data.groupName,
      paymentMode: data.paymentMode,
      expectedCount: data.count,
      groupPaid: false,
      players: [],
      status: "activa",
      deposit: data.depositAmount > 0 ? { amount: data.depositAmount, status: "pendiente" } : null,
      createdAt: Date.now(),
    };
    persist([r, ...reservations]);
    setActiveId(r.id);
    setView("lista");
  }

  if (reservations === null) {
    return (
      <div className="min-h-screen bg-stone-50 flex items-center justify-center">
        <div className="text-orange-600 font-mono text-base tracking-widest animate-pulse">CARGANDO CAMPO...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-stone-50 text-stone-900 font-sans">
      {view !== "inicio" && <Header saving={saving} view={view} setView={setView} />}
      {view === "inicio" ? (
        <InicioView setView={setView} reservations={reservations} />
      ) : (
        <main className="max-w-2xl mx-auto px-4 pb-24 pt-4">
          {view === "lista" && (
            <ListaReservas
              reservations={reservations}
              onOpen={(id) => {
                setActiveId(id);
                setView("detalle");
              }}
              onNew={() => setView("nueva")}
            />
          )}
          {view === "nueva" && (
            <NuevaReserva
              onCancel={() => setView("lista")}
              onCreate={createReservation}
              initialDate={prefill?.date}
              initialTime={prefill?.time}
            />
          )}
          {view === "detalle" && active && (
            <DetalleReserva
              r={active}
              onBack={() => setView("lista")}
              onUpdate={(fn) => updateReservation(active.id, fn)}
              onDelete={() => deleteReservation(active.id)}
              favorites={favorites}
              onToggleFavorite={(player) => {
                const exists = favorites.find((f) => f.name.trim().toLowerCase() === player.name.trim().toLowerCase());
                if (exists) {
                  persistFavorites(favorites.filter((f) => f.id !== exists.id));
                } else {
                  persistFavorites([...favorites, { id: uid(), name: player.name, phone: "", notes: "" }]);
                }
              }}
            />
          )}
          {view === "reporte" && <Reporte reservations={reservations} />}
          {view === "semana" && (
            <SemanaView
              reservations={reservations}
              onOpen={(id) => {
                setActiveId(id);
                setView("detalle");
              }}
              onNewAt={(date, time) => {
                setPrefill({ date, time });
                setView("nueva");
              }}
            />
          )}
          {view === "favoritos" && (
            <FavoritosView favorites={favorites} onSave={persistFavorites} />
          )}
        </main>
      )}
      {loadError && (
        <div className="fixed bottom-4 left-4 right-4 bg-red-600 text-white text-sm px-3 py-2 rounded-md flex items-start justify-between gap-3 z-50">
          <div className="min-w-0">
            <div className="font-bold">No se pudo guardar</div>
            <div className="text-[12px] opacity-90 break-words">{loadError}</div>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            {pendingRetry && (
              <button
                onClick={retrySave}
                className="text-[12px] font-bold uppercase bg-white text-red-600 rounded px-2 py-1"
              >
                Reintentar
              </button>
            )}
            <button onClick={() => setLoadError(null)} className="font-bold">
              <X size={16} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

