function ListaReservas({ reservations, onOpen, onNew }) {
  const today = todayStr();
  const active = reservations.filter((r) => r.status !== "cancelada");
  const cancelled = reservations
    .filter((r) => r.status === "cancelada")
    .sort((a, b) => `${b.date} ${b.time}`.localeCompare(`${a.date} ${a.time}`));
  const pending = active
    .filter((r) => r.date >= today)
    .sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));
  const past = active
    .filter((r) => r.date < today)
    .sort((a, b) => `${b.date} ${b.time}`.localeCompare(`${a.date} ${a.time}`));

  return (
    <div className="pt-2">
      <button
        onClick={onNew}
        className="w-full mb-4 bg-orange-600 hover:bg-orange-500 text-stone-50 font-bold rounded-lg py-3 flex items-center justify-center gap-2 transition-colors"
      >
        <Plus size={18} strokeWidth={2.5} /> Nueva reserva
      </button>

      {reservations.length === 0 && (
        <div className="text-center text-stone-500 py-16 text-base">
          Todavía no hay reservas. Crea la primera.
        </div>
      )}

      {pending.length > 0 && (
        <div className="space-y-2">
          {pending.map((r) => (
            <ReservaCard key={r.id} r={r} onOpen={onOpen} />
          ))}
        </div>
      )}
      {pending.length === 0 && reservations.length > 0 && (
        <div className="text-center text-stone-500 py-6 text-sm">No hay reservas pendientes.</div>
      )}

      {past.length > 0 && (
        <div className="mt-8">
          <div className="text-sm text-stone-500 uppercase tracking-wide font-semibold mb-2">
            Reservas pasadas
          </div>
          <div className="space-y-2 opacity-70">
            {past.map((r) => (
              <ReservaCard key={r.id} r={r} onOpen={onOpen} />
            ))}
          </div>
        </div>
      )}

      {cancelled.length > 0 && (
        <div className="mt-8">
          <div className="text-sm text-stone-500 uppercase tracking-wide font-semibold mb-2">
            Canceladas
          </div>
          <div className="space-y-2 opacity-60">
            {cancelled.map((r) => (
              <ReservaCard key={r.id} r={r} onOpen={onOpen} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function ReservaCard({ r, onOpen }) {
  const total = reservationTotal(r);
  const paid = reservationPaid(r);
  const fullyPaid = paid >= total;
  const started = r.players.length > 0;
  const cancelled = r.status === "cancelada";
  return (
    <button
      onClick={() => onOpen(r.id)}
      className={`w-full text-left border rounded-lg p-3 transition-colors ${
        cancelled
          ? "bg-red-50 border-red-200 hover:bg-red-100"
          : "bg-stone-100 hover:bg-stone-200 border-stone-200"
      }`}
    >
      <div className="flex items-center justify-between">
        <div>
          <div className={`font-bold text-base ${cancelled ? "line-through text-stone-500" : ""}`}>
            {r.groupName || "Sin nombre"}
          </div>
          <div className="text-sm text-stone-500 flex items-center gap-2 mt-0.5">
            <Calendar size={12} /> {r.date} · {r.time}
            <Users size={12} className="ml-1" />
            {started ? r.players.length : `~${r.expectedCount ?? "?"} esperados`}
          </div>
        </div>
        <div className="text-right">
          {cancelled ? (
            <div className="text-[12px] font-semibold uppercase tracking-wide text-red-600 bg-red-100 px-2 py-1 rounded">
              Cancelada
            </div>
          ) : started ? (
            <>
              <div className="font-black text-orange-600">${total}</div>
              <div
                className={`text-[12px] font-semibold uppercase tracking-wide ${
                  fullyPaid ? "text-emerald-500" : "text-stone-500"
                }`}
              >
                {fullyPaid ? "Pagado" : `Debe $${(total - paid).toFixed(0)}`}
              </div>
            </>
          ) : (
            <div className="text-[12px] font-semibold uppercase tracking-wide text-stone-500 bg-stone-200 px-2 py-1 rounded">
              Reservado
            </div>
          )}
        </div>
      </div>
      {!cancelled && r.deposit && r.deposit.status === "pendiente" && (
        <div className="mt-2 text-[12px] font-semibold text-teal-600 bg-teal-500/10 inline-block px-2 py-1 rounded">
          Abono ${r.deposit.amount} por resolver
        </div>
      )}
    </button>
  );
}

